files.src/clamp.cjs:
'use strict';
function clamp(value, lower, upper) {
  if (![value, lower, upper].every(Number.isFinite) || lower > upper) throw new RangeError('invalid range');
  return Math.max(lower, Math.min(upper, value));
}
function clampMany(values,lower,upper){if(!Array.isArray(values))throw new TypeError('array required');return values.map(value=>clamp(value,lower,upper));}
module.exports={clamp,clampMany};

